/**
 * Frozen cross-module contracts for dsh-plugin-evo-harness.
 *
 * OWNERSHIP (Wave 0, do not edit downstream):
 * - package.json, tsconfig.json, src/config.ts, src/types/** are owned by the
 *   contract architect. Wave 1 modules must import these types and must not
 *   modify this directory. Report contract gaps to the captain instead of
 *   editing this file.
 * - Each Wave 1 module owns its own source directory and unit-test directory:
 *   src/cordis-seams/**, src/memory-bridge/**, src/harness2/**, src/dream-rsi/**.
 *   src/index.ts and src/orchestrator.ts are owned by the integrator.
 *
 * HOST API ASSUMPTIONS (unavoidable, recorded for downstream agents):
 * 1. Cordis: this package does NOT import the host 'cordis' package. The seam
 *    layer adapts a structural host context. The host is assumed to provide:
 *    child-context forking, prompt segment registration, guardrail/permission
 *    hooks, tool-description patching, dynamic skill mounting, sandbox script
 *    mounting, dynamic subagent registration, and tool-loop middleware, each
 *    returning an idempotent disposer. Actual ctx.* wiring belongs to
 *    src/cordis-seams/**. Tests must use structural fakes, never the real host.
 * 2. MCP: the memory layer talks to an injectable MCP client. The host client is
 *    assumed to expose tools/list introspection (name, description, JSON-Schema
 *    input) and tools/call with JSON-serializable arguments and content blocks.
 *    Concrete client and driver types belong to src/memory-bridge/**; only the
 *    stable IMemoryBridge facade is frozen here.
 * 3. Time and identifiers: all timestamps are UTC epoch milliseconds; all ids
 *    are opaque non-empty strings generated by the owning module. Never parse
 *    ids for meaning. Metadata bags are JSON-serializable.
 * 4. Determinism: implementations must accept injected model/MCP/host adapters
 *    so unit tests and E2E tests run without network, LLM, or sandbox access.
 *    Contracts therefore use structural interfaces, plain data records, and
 *    no classes or decorators.
 * 5. Metrics: ProbeTrajectory.metrics is computed by the seam/trajectory
 *    collector from observed steps (steps = steps.length; toolCalls = count of
 *    kind 'tool'; toolErrors = toolErrors.length; durationMs = end - start).
 *    Surrogate scores are clamped to [0, 1] by the scorer.
 * 6. Negative evidence: CanonicalLesson.polarity 'negative' entries are failure
 *    lessons and must never be injected as recommendations. The memory bridge
 *    separates them into anti-pattern warnings after recall.
 *
 * CONTRACT VERSION: 2. Version 2 is a purely additive round for JitRL (Phase 1):
 * it adds the experience / adjustment / step-evaluation contracts, two new
 * ModelPurpose values, optional logprob and candidateCount request fields, and
 * the optional MetaSearchPolicy.jit hyperparameters. No version 1 export was
 * renamed, removed or widened. A breaking change requires a new contract round;
 * do not silently widen or rename exported fields.
 *
 * Version 2 stays the current version for the Phase 4/5 additive round: the
 * Dream-RSI x JitRL replay hook, the L3 host-advisor tri-state decision, and the
 * JitRL statistics mirror contracts append new exports and optional fields only
 * (see the "JitRL Phase 4/5" section below). Nothing already exported was
 * renamed, removed, widened or made required.
 *
 * Version 2 also stays current for P6 (plan section 6.1): the per-execution
 * credit-attribution fields on ExperienceRecord and the legacy/eligibility
 * filters on ExperienceQuery are OPTIONAL additions, so no existing producer or
 * consumer changes behaviour. The persisted-record format is versioned
 * separately by ExperienceRecord.experienceSchemaVersion (see
 * EXPERIENCE_SCHEMA_VERSION in src/jitrl/experience-store.ts) rather than by
 * bumping CONTRACT_SCHEMA_VERSION: an old JSONL line still loads, it is simply
 * classified as legacy and kept out of the new learning neighbourhood.
 */

/** Version of the frozen contract surface. */
export const CONTRACT_SCHEMA_VERSION = 2 as const;

/**
 * The eight editable Harness² surfaces, mapped 1:1 onto Cordis capability seams
 * (see ARCHITECTURE.md section 3). Order is stable and used to mount surfaces.
 */
export const HARNESS_COMPONENT_KEYS = [
  'system_prompt',
  'guardrails',
  'memory',
  'tool_guidance',
  'skills',
  'scripts',
  'subagents',
  'plugins'
] as const;

/** One of the eight editable harness components. */
export type HarnessComponentKey = (typeof HARNESS_COMPONENT_KEYS)[number];

/** How a candidate patch was produced (memory-guided vs guidance-free). */
export const PATCH_ORIGINS = ['reference', 'domain', 'invariant', 'composed'] as const;
export type PatchOrigin = (typeof PATCH_ORIGINS)[number];

/** Why a candidate patch exists in the search tree. */
export const PATCH_PURPOSES = ['initial', 'deepen', 'explore', 'repair', 'compose'] as const;
export type PatchPurpose = (typeof PATCH_PURPOSES)[number];

/**
 * Whether external memory guidance was allowed for a patch/proposal.
 * 'guidance_free' is required for invariant exploration branches so recalled
 * lessons can never contaminate first-principles exploration.
 */
export type GuidanceMode = 'memory' | 'guidance_free';

/** Stable trigger modes from ARCHITECTURE.md section 6.2. */
export const TRIGGER_MODES = ['auto_fallback', 'always', 'slash_command'] as const;
export type TriggerMode = (typeof TRIGGER_MODES)[number];

/** Coarse task complexity used by plan_grid. */
export const TASK_COMPLEXITIES = ['trivial', 'simple', 'moderate', 'complex', 'unknown'] as const;
export type TaskComplexity = (typeof TASK_COMPLEXITIES)[number];

/** JSON-serializable metadata bag. Values may be nested plain JSON data. */
export type ContractMetadata = Readonly<Record<string, unknown>>;

// ---------------------------------------------------------------------------
// Eight-surface patch model
// ---------------------------------------------------------------------------

/** A pre-tool-call rule attached to the guardrails surface. */
export interface ToolPrecondition {
  readonly toolName: string;
  readonly rule: string;
}

/** System prompt segment edit (Cordis prompt.registerSegment seam). */
export interface SystemPromptSurfaceEdit {
  readonly kind: 'system_prompt';
  readonly mode: 'append' | 'replace';
  readonly content: string;
  readonly segment?: string;
  readonly priority?: number;
}

/** Guardrails edit: output contracts, forbidden actions, tool preconditions. */
export interface GuardrailsSurfaceEdit {
  readonly kind: 'guardrails';
  readonly appendRules?: readonly string[];
  readonly forbiddenActions?: readonly string[];
  readonly formatContract?: string;
  readonly toolPreconditions?: readonly ToolPrecondition[];
}

/**
 * Memory surface edit. Branch isolation is enforced by the memory bridge: the
 * scoped view id should equal the probe branch namespace. Working notes are
 * in-branch scratchpad content and must never be promoted globally.
 */
export interface MemorySurfaceEdit {
  readonly kind: 'memory';
  readonly scopedViewId?: string;
  readonly workingNotes?: readonly string[];
  readonly recallTags?: readonly string[];
}

/** Example attached to a patched tool description. */
export interface ToolGuidanceExample {
  readonly toolName: string;
  readonly example: string;
}

/** Tool guidance edit: descriptions, priority and examples only. */
export interface ToolGuidanceSurfaceEdit {
  readonly kind: 'tool_guidance';
  readonly descriptions: Readonly<Record<string, string>>;
  readonly priorityOrder?: readonly string[];
  readonly examples?: readonly ToolGuidanceExample[];
}

/** A dynamically mounted SKILL.md-style SOP. */
export interface DynamicSkillSpec {
  readonly name: string;
  readonly markdown: string;
  readonly description?: string;
  readonly activate?: boolean;
}

/** Skills surface edit: in-memory skill mounting. */
export interface SkillsSurfaceEdit {
  readonly kind: 'skills';
  readonly skills: readonly DynamicSkillSpec[];
}

/** A helper script mounted into a branch-private sandbox workspace. */
export interface ScriptArtifactSpec {
  readonly path: string;
  readonly language: 'python' | 'bash' | 'typescript' | 'javascript';
  readonly code: string;
  readonly executable?: boolean;
}

/** Scripts surface edit. */
export interface ScriptsSurfaceEdit {
  readonly kind: 'scripts';
  readonly scripts: readonly ScriptArtifactSpec[];
}

/** A dynamically registered subagent specification. */
export interface SubagentSpec {
  readonly name: string;
  readonly description: string;
  readonly systemPrompt?: string;
  readonly tools?: readonly string[];
  readonly model?: string;
}

/** Subagents surface edit. */
export interface SubagentsSurfaceEdit {
  readonly kind: 'subagents';
  readonly agents: readonly SubagentSpec[];
}

/** Tool-loop middleware hook point. */
export type MiddlewareHook = 'before_tool' | 'after_tool' | 'around_tool';

/** A generated tool-loop interceptor. */
export interface MiddlewareSpec {
  readonly name: string;
  readonly hook: MiddlewareHook;
  readonly language: 'typescript' | 'javascript';
  readonly code: string;
  readonly description?: string;
}

/** Plugins surface edit: dynamic middleware mounting. */
export interface PluginsSurfaceEdit {
  readonly kind: 'plugins';
  readonly middleware: readonly MiddlewareSpec[];
}

/** Per-key payload map for the eight surfaces. */
export interface SurfacePayloadMap {
  system_prompt: SystemPromptSurfaceEdit;
  guardrails: GuardrailsSurfaceEdit;
  memory: MemorySurfaceEdit;
  tool_guidance: ToolGuidanceSurfaceEdit;
  skills: SkillsSurfaceEdit;
  scripts: ScriptsSurfaceEdit;
  subagents: SubagentsSurfaceEdit;
  plugins: PluginsSurfaceEdit;
}

/** Payload type for a specific surface key. */
export type SurfacePayloadFor<K extends HarnessComponentKey> = SurfacePayloadMap[K];

/** Union of every supported surface payload (discriminated by 'kind'). */
export type SupportedSurfacePayload = SurfacePayloadMap[HarnessComponentKey];

/** Sparse edits for any subset of the eight surfaces. */
export type EightSurfaceEdits = {
  readonly [K in HarnessComponentKey]?: SurfacePayloadMap[K];
};

/**
 * A complete candidate scaffold edit applied inside one branch.
 * Composer emits purpose 'compose'/origin 'composed' for the selected H*.
 */
export interface EightSurfacePatch {
  readonly id: string;
  readonly sessionId: string;
  readonly branchId: string;
  readonly origin: PatchOrigin;
  readonly purpose: PatchPurpose;
  readonly guidance: GuidanceMode;
  readonly label: string;
  readonly rationale: string;
  readonly edits: EightSurfaceEdits;
  readonly parentPatchIds?: readonly string[];
  readonly sourceLessonIds?: readonly string[];
  readonly createdAt: number;
  readonly metadata?: ContractMetadata;
}

/** Handle returned by applyPermanentPatch; dispose is idempotent. */
export interface SurfacePatchDisposer {
  readonly patchId: string;
  readonly active: boolean;
  dispose(): Promise<void>;
}

// ---------------------------------------------------------------------------
// Trajectory records
// ---------------------------------------------------------------------------

/** The role of a run in a contrastive probe pair. */
export type TrajectoryRole = 'reference' | 'candidate';

/** Terminal status of a probe run. */
export type TrajectoryStatus = 'succeeded' | 'failed' | 'timeout' | 'aborted';

/** Step kinds recorded by the Cordis trajectory collector. */
export type TrajectoryStepKind = 'model' | 'tool' | 'system' | 'message' | 'result' | 'error';

/** One event-sourced trajectory step. Tool payloads are opaque JSON values. */
export interface TrajectoryStep {
  readonly index: number;
  readonly at: number;
  readonly kind: TrajectoryStepKind;
  readonly toolName?: string;
  readonly toolArguments?: unknown;
  readonly toolResult?: unknown;
  readonly text?: string;
  readonly error?: TrajectoryError;
  readonly durationMs?: number;
  readonly metadata?: ContractMetadata;
}

/** Serialized error captured in a trajectory. */
export interface TrajectoryError {
  readonly name: string;
  readonly message: string;
  readonly code?: string;
  readonly stack?: string;
}

/** Structured tool error used by the failure taxonomy. */
export interface ToolErrorRecord {
  readonly toolName: string;
  readonly message: string;
  readonly code?: string;
  readonly retryable?: boolean;
  readonly stepIndex?: number;
  readonly at?: number;
  readonly stack?: string;
  readonly metadata?: ContractMetadata;
}

/** Token accounting for a run, when the host exposes it. */
export interface TokenUsage {
  readonly inputTokens: number;
  readonly outputTokens: number;
  readonly totalTokens: number;
}

/** Concrete output produced by a candidate run, used for anonymous comparison. */
export interface TrajectoryDeliverable {
  readonly content: string;
  readonly format?: 'text' | 'markdown' | 'json' | 'patch' | 'code';
  readonly contentHash?: string;
  readonly producedFiles?: readonly string[];
}

/** Deterministic metrics required by the surrogate scorer. */
export interface TrajectoryMetrics {
  readonly steps: number;
  readonly toolCalls: number;
  readonly toolErrors: number;
  readonly durationMs: number;
  readonly inputTokens?: number;
  readonly outputTokens?: number;
  readonly totalTokens?: number;
  readonly deliverableChars?: number;
}

/** Signals that feed the four-way failure taxonomy. */
export type FailureSignalKind =
  | 'tool_error'
  | 'syntax_error'
  | 'import_error'
  | 'timeout'
  | 'no_deliverable'
  | 'invalid_patch'
  | 'memory_conflict'
  | 'budget_exhausted'
  | 'model_refusal'
  | 'repeated_failure'
  | 'unknown';

/** One observed failure signal on a trajectory. */
export interface FailureSignal {
  readonly kind: FailureSignalKind;
  readonly message: string;
  readonly stepIndex?: number;
  readonly toolName?: string;
  readonly retryable?: boolean;
  readonly repairable?: boolean;
  readonly code?: string;
  readonly evidence?: string;
}

/** Failure categories from Dream-RSI's four-way taxonomy (plus 'none'). */
export const FAILURE_CATEGORIES = [
  'hard_unrecoverable',
  'repairable_implementation',
  'weak_underexplored',
  'repeatedly_unpromising',
  'none'
] as const;
export type FailureCategory = (typeof FAILURE_CATEGORIES)[number];

/** Diagnosis produced by failure-taxonomy.ts for a completed node/branch. */
export interface FailureDiagnosis {
  readonly category: FailureCategory;
  readonly confidence: number;
  readonly repairable: boolean;
  readonly recommendedAction: 'repair' | 'deepen' | 'explore_elsewhere' | 'discard' | 'stop';
  readonly evidence: readonly string[];
  readonly signals: readonly FailureSignal[];
  readonly repairHint?: string;
}

/**
 * The stable observable record of one reference or candidate probe.
 * Produced by ICordisSeamManager.runInIsolatedBranch and consumed by the
 * composer, failure taxonomy, surrogate scorer, reflector and offline replay.
 */
export interface ProbeTrajectory {
  readonly id: string;
  readonly sessionId: string;
  readonly branchId: string;
  readonly branchNamespace: string;
  readonly role: TrajectoryRole;
  readonly status: TrajectoryStatus;
  readonly patchId: string;
  readonly patchOrigin: PatchOrigin;
  readonly surfaceKeys: readonly HarnessComponentKey[];
  readonly treeId?: string;
  readonly nodeId?: string;
  readonly referenceTrajectoryId?: string;
  readonly startedAt: number;
  readonly endedAt: number;
  readonly metrics: TrajectoryMetrics;
  readonly steps: readonly TrajectoryStep[];
  readonly toolErrors: readonly ToolErrorRecord[];
  readonly deliverable?: TrajectoryDeliverable;
  readonly failureSignals: readonly FailureSignal[];
  readonly memoryRecallIds: readonly string[];
  readonly error?: TrajectoryError;
  readonly metadata?: ContractMetadata;
}

// ---------------------------------------------------------------------------
// Universal MCP memory bridge
// ---------------------------------------------------------------------------

/** Adapter families from ARCHITECTURE.md section 4.2. */
export const MEMORY_DRIVER_KINDS = [
  'graph_entity',
  'vector_fact',
  'temporal_graph',
  'markdown_note',
  'lingshu_mdcg',
  'custom_mapped'
] as const;
export type MemoryDriverKind = (typeof MEMORY_DRIVER_KINDS)[number];

/** Driver kind or 'unbound' before auto-discovery completes. */
export type MemoryBindingKind = MemoryDriverKind | 'unbound';

/** Scope kinds supported by virtual namespace isolation. */
export type MemoryScopeKind = 'global' | 'session' | 'branch';

/**
 * A deterministic namespace scope. The bridge derives the concrete namespace
 * from configuration plus these fields; callers never invent namespace strings.
 */
export type MemoryScope =
  | { readonly kind: 'global' }
  | { readonly kind: 'session'; readonly sessionId: string }
  | { readonly kind: 'branch'; readonly sessionId: string; readonly branchId: string };

/** Handle for a branch/session isolation scope created by IMemoryBridge.isolate. */
export interface MemoryIsolationHandle {
  readonly scope: MemoryScope;
  readonly namespace: string;
  readonly active: boolean;
  release(): Promise<void>;
}

/** Positive or negative lesson polarity. */
export type LessonPolarity = 'positive' | 'negative';

/** Visibility of a lesson, used for promotion from branch to global scope. */
export type LessonVisibility = 'branch_private' | 'session' | 'global';

/** Concrete harness edit embedded in a lesson (CCG element 4). */
export interface LessonExecutionPatch {
  readonly summary: string;
  readonly componentDiffs?: Readonly<Record<string, string>>;
  readonly patchId?: string;
}

/** Behavioral contrast metrics attached to a lesson (CCG element 5). */
export interface LessonMetricsDelta {
  readonly stepsDiff: number;
  readonly toolErrorsDiff: number;
}

/** Probe evidence proving the lesson (CCG element 5). */
export interface LessonVerificationEvidence {
  readonly referenceFailure: string;
  readonly candidateSuccess: string;
  readonly metricsDelta: LessonMetricsDelta;
  readonly referenceTrajectoryId?: string;
  readonly candidateTrajectoryId?: string;
}

/**
 * Canonical Lesson Envelope (ARCHITECTURE.md 4.1), a CCG-compatible superset.
 * The six CCG elements are mandatory; governance extension fields are optional
 * with documented defaults. Negative lessons carry the same shape and must be
 * used only as anti-patterns.
 */
export interface CanonicalLesson {
  readonly id: string;
  readonly title: string;
  readonly whenToApply: readonly string[];
  readonly subFunctions: readonly HarnessComponentKey[];
  readonly executionPatch: LessonExecutionPatch;
  readonly verificationEvidence: LessonVerificationEvidence;
  readonly whenNotToApply: readonly string[];
  readonly polarity: LessonPolarity;
  readonly visibility: LessonVisibility;
  readonly sessionId: string;
  readonly branchId?: string;
  readonly schemaVersion?: 1;
  readonly createdAt?: number;
  readonly tags?: readonly string[];
  readonly confidence?: number;
  readonly taskSignature?: string;
  readonly sourceTreeId?: string;
  readonly metadata?: ContractMetadata;
}

/** Client-side governance rejection codes. */
export const GOVERNANCE_VIOLATION_CODES = [
  'invalid_lesson',
  'missing_when_to_apply',
  'missing_when_not_to_apply',
  'missing_verification_evidence',
  'invalid_execution_patch',
  'invalid_sub_functions',
  'script_syntax_invalid',
  'invalid_script_path',
  'namespace_violation',
  'scope_violation',
  'negative_polarity_leak',
  'duplicate_lesson',
  'unsupported_operation'
] as const;
export type GovernanceViolationCode = (typeof GOVERNANCE_VIOLATION_CODES)[number];

/** A blocking or warning governance finding. */
export interface GovernanceViolation {
  readonly code: GovernanceViolationCode;
  readonly message: string;
  readonly field?: string;
  readonly severity: 'block' | 'warn';
  readonly evidence?: string;
}

/** Query for memory recall. The bridge applies scope + firewall filtering. */
export interface MemoryRecallQuery {
  readonly scope: MemoryScope;
  readonly text: string;
  readonly taskSignature?: string;
  readonly contextTags?: readonly string[];
  readonly limit?: number;
  readonly includeNegative?: boolean;
  readonly minConfidence?: number;
  readonly metadata?: ContractMetadata;
}

/** Why a recalled lesson was withheld from the model. */
export type SuppressionReason =
  | 'when_not_to_apply'
  | 'governance_violation'
  | 'scope_mismatch'
  | 'low_confidence'
  | 'negative_polarity_filtered'
  | 'other';

/** A lesson that recall intentionally filtered out. */
export interface SuppressedLesson {
  readonly lessonId: string;
  readonly title: string;
  readonly reason: SuppressionReason;
  readonly detail: string;
}

/**
 * Recall result. lessons === positiveLessons + negativeLessons after filtering;
 * negativeLessons are anti-pattern warnings, never recommendations. confidence
 * is the aggregate memory confidence in [0, 1] used by plan_grid (0 when the
 * backend is unbound or no lesson matched).
 */
export interface MemoryRecallResult {
  readonly query: MemoryRecallQuery;
  readonly scope: MemoryScope;
  readonly driverKind: MemoryBindingKind;
  readonly lessons: readonly CanonicalLesson[];
  readonly positiveLessons: readonly CanonicalLesson[];
  readonly negativeLessons: readonly CanonicalLesson[];
  readonly suppressedLessons: readonly SuppressedLesson[];
  readonly confidence: number;
  readonly degraded: boolean;
  readonly diagnostics: readonly string[];
  readonly recalledAt: number;
}

/** Options for a governed memory commit. */
export interface MemoryCommitOptions {
  readonly scope: MemoryScope;
  readonly enforceGovernance?: boolean;
  readonly dryRun?: boolean;
  readonly metadata?: ContractMetadata;
}

/** Result of a commit attempt. A blocked lesson must have accepted=false. */
export interface MemoryCommitResult {
  readonly accepted: boolean;
  readonly persisted: boolean;
  readonly lessonId: string;
  readonly namespace: string;
  readonly driverKind: MemoryBindingKind;
  readonly violations: readonly GovernanceViolation[];
  readonly backendRef?: string;
  readonly at: number;
}

/** Options for promoting a winning lesson out of a branch scope. */
export interface MemoryPromoteOptions {
  readonly from: MemoryScope;
  readonly to?: MemoryScope;
  readonly metadata?: ContractMetadata;
}

/** Options for pruned cleanup. */
export interface MemoryPruneOptions {
  readonly scope: MemoryScope;
  readonly olderThan?: number;
  readonly ids?: readonly string[];
  readonly polarity?: LessonPolarity;
  readonly dryRun?: boolean;
  readonly maxItems?: number;
}

/** Result of prune; ids are reported even in dry-run mode. */
export interface MemoryPruneResult {
  readonly scanned: number;
  readonly removedIds: readonly string[];
  readonly dryRun: boolean;
}

/** Backend capabilities discovered during auto-discovery. */
export interface MemoryBackendCapabilities {
  readonly metadataFiltering: boolean;
  readonly namespaces: boolean;
  readonly negativePolarity: boolean;
  readonly temporal: boolean;
  readonly supportsPrune: boolean;
}

/** Stable description of the bound MCP memory backend. */
export interface MemoryBridgeDescriptor {
  readonly driverKind: MemoryBindingKind;
  readonly serverId: string | null;
  readonly backendLabel: string;
  readonly capabilities: MemoryBackendCapabilities;
  readonly boundAt: number;
  readonly diagnostics: readonly string[];
}

/**
 * Unified Memory SPI (recall / commit / isolate / prune). Implementations wrap
 * any MCP memory backend behind a driver. All methods must be safe to mock:
 * no host-specific types may leak into this facade.
 */
export interface IMemoryBridge {
  readonly descriptor: MemoryBridgeDescriptor;
  initialize(): Promise<MemoryBridgeDescriptor>;
  recall(query: MemoryRecallQuery): Promise<MemoryRecallResult>;
  commit(lesson: CanonicalLesson, options: MemoryCommitOptions): Promise<MemoryCommitResult>;
  isolate(scope: MemoryScope): Promise<MemoryIsolationHandle>;
  promote(lesson: CanonicalLesson, options: MemoryPromoteOptions): Promise<MemoryCommitResult>;
  prune(options: MemoryPruneOptions): Promise<MemoryPruneResult>;
  dispose(): Promise<void>;
}

// ---------------------------------------------------------------------------
// Cordis seam manager and probe execution
// ---------------------------------------------------------------------------

/** A user task routed into the evolution runtime. */
export interface ProbeTask {
  readonly id: string;
  readonly prompt: string;
  readonly taskSignature?: string;
  readonly complexity?: TaskComplexity;
  readonly contextTags?: readonly string[];
  readonly metadata?: ContractMetadata;
}

/**
 * Branch-scoped view handed to the injected executor. Every field is immutable;
 * the seam manager owns cleanup. mountedSurfaces lists the surfaces actually
 * mounted for the patch (all eight when edits cover all eight).
 */
export interface IsolatedBranchContext {
  readonly branchId: string;
  readonly sessionId: string;
  readonly namespace: string;
  readonly task: ProbeTask;
  readonly patch: EightSurfacePatch;
  readonly mountedSurfaces: readonly HarnessComponentKey[];
  readonly signal: AbortSignal;
  readonly metadata?: ContractMetadata;
}

/** Outcome returned by the injected branch executor. */
export interface ProbeExecutionResult {
  readonly status?: TrajectoryStatus;
  readonly steps?: readonly TrajectoryStep[];
  readonly deliverable?: TrajectoryDeliverable;
  readonly toolErrors?: readonly ToolErrorRecord[];
  readonly usage?: TokenUsage;
  readonly failureSignals?: readonly FailureSignal[];
  readonly error?: TrajectoryError;
  readonly metadata?: ContractMetadata;
}

/** Injected branch body. The seam manager supplies context and cleanup. */
export type BranchExecutor = (context: IsolatedBranchContext) => Promise<ProbeExecutionResult>;

/** Request for one isolated probe run. */
export interface ProbeBranchRequest {
  readonly sessionId: string;
  readonly task: ProbeTask;
  readonly patch: EightSurfacePatch;
  readonly executor: BranchExecutor;
  readonly branchId?: string;
  readonly role?: TrajectoryRole;
  readonly treeId?: string;
  readonly nodeId?: string;
  readonly referenceTrajectoryId?: string;
  readonly memoryRecallIds?: readonly string[];
  readonly timeoutMs?: number;
  readonly signal?: AbortSignal;
  readonly metadata?: ContractMetadata;
}

/** Summary of an active isolated branch. */
export interface BranchSummary {
  readonly branchId: string;
  readonly sessionId: string;
  readonly namespace: string;
  readonly patchId: string;
  readonly mountedSurfaces: readonly HarnessComponentKey[];
  readonly startedAt: number;
}

/**
 * Cordis eight-surface seam manager. runInIsolatedBranch must dispose every
 * reversible effect on success, failure, timeout and abort. applyPermanentPatch
 * must return an idempotent disposer that rolls back all registered effects.
 */
export interface ICordisSeamManager {
  runInIsolatedBranch(request: ProbeBranchRequest): Promise<ProbeTrajectory>;
  applyPermanentPatch(patch: EightSurfacePatch): Promise<SurfacePatchDisposer>;
  listActiveBranches(): readonly BranchSummary[];
  dispose(): Promise<void>;
}

// ---------------------------------------------------------------------------
// Injected model adapter (host-neutral LLM boundary)
// ---------------------------------------------------------------------------

/**
 * Why a model call is being made; useful for deterministic fakes.
 *
 * 'probe' marks model calls made inside an isolated probe branch (the branch
 * execution / multi-step agent probe loop). Probe traffic must stay
 * distinguishable from 'compose' judging in routing and usage statistics: a
 * probe runs the candidate scaffold itself, while 'compose' only ranks
 * anonymized probe results afterwards.
 */
export type ModelPurpose =
  | 'propose'
  | 'compose'
  | 'reflect'
  | 'dream_policy'
  | 'probe'
  | 'evaluate_steps'
  | 'abstract_state';

/** One chat-style model message. */
export interface ModelMessage {
  readonly role: 'system' | 'user' | 'assistant';
  readonly content: string;
}

/** A model request with no provider-specific fields. */
export interface ModelRequest {
  readonly purpose: ModelPurpose;
  readonly messages: readonly ModelMessage[];
  readonly temperature?: number;
  readonly maxTokens?: number;
  readonly responseFormat?: 'text' | 'json';
  readonly metadata?: ContractMetadata;
  /** Optional top-K token logprob request; providers without support ignore it. */
  readonly logprobs?: { readonly topK: number };
}

/** A model response with optional usage accounting. */
export interface ModelResponse {
  readonly text: string;
  readonly finishReason?: 'stop' | 'length' | 'error' | 'tool_calls' | 'unknown';
  readonly usage?: TokenUsage;
  readonly model?: string;
  readonly metadata?: ContractMetadata;
  /** Per-token logprobs when requested and reported by the provider. */
  readonly tokenLogprobs?: readonly {
    readonly token: string;
    readonly logprob: number;
    readonly top?: readonly { readonly token: string; readonly logprob: number }[];
  }[];
}

/** Injectable LLM adapter used by Harness² and Dream-RSI policy generation. */
export interface IModelAdapter {
  complete(request: ModelRequest): Promise<ModelResponse>;
}

// ---------------------------------------------------------------------------
// Harness²: propose / compose / reflect
// ---------------------------------------------------------------------------

/**
 * Memory guidance is structurally asymmetric: only 'domain' may carry recalled
 * memory; 'invariant' has memory: null and must never receive external lessons.
 * When asymmetric guidance is disabled by config, slots use 'domain' only.
 */
export interface DomainProposerGuidance {
  readonly mode: 'domain';
  readonly memory: MemoryRecallResult;
}

/** Guidance-free invariant exploration. memory is null by construction. */
export interface InvariantProposerGuidance {
  readonly mode: 'invariant';
  readonly memory: null;
}

/** Discriminated guidance handed to the proposer. */
export type ProposerGuidance = DomainProposerGuidance | InvariantProposerGuidance;

/** Input for one slot-specific proposal. */
export interface ProposeRequest {
  readonly task: ProbeTask;
  readonly sessionId: string;
  readonly slot: BatchSlotPlan;
  readonly guidance: ProposerGuidance;
  readonly parentNode?: DiscoveryNode;
  readonly parentPatch?: EightSurfacePatch;
  readonly referenceTrajectory?: ProbeTrajectory;
  readonly enabledSurfaces?: readonly HarnessComponentKey[];
  readonly attemptIndex: number;
  readonly totalBudget: number;
  readonly metadata?: ContractMetadata;
  /** Number of candidates to propose (K); defaults to 1 for backward compatibility. */
  readonly candidateCount?: number;
}

/** A candidate patch plus its rationale and focus. */
export interface ProposedPatch {
  readonly patch: EightSurfacePatch;
  readonly rationale: string;
  readonly focusSurfaces: readonly HarnessComponentKey[];
  readonly confidence: number;
  readonly expectedStepsDelta?: number;
}

/**
 * K-candidate proposal payload returned by the optional multi-candidate
 * proposer path (plan section 8 Phase 3, L2). Each candidate keeps its own
 * confidence and patch; the list is readonly so downstream selection cannot
 * mutate the proposer's output.
 */
export interface ProposedPatchSet {
  readonly candidates: readonly ProposedPatch[];
}

/** Dual-track proposer (Domain vs Invariant). */
export interface IHarnessProposer {
  propose(request: ProposeRequest): Promise<ProposedPatch>;
  /**
   * Optional multi-candidate path: return K candidates in one proposer call
   * (K = request.candidateCount, default 1). Implementations that omit this
   * method keep the single-candidate behaviour of propose().
   */
  proposeCandidates?(request: ProposeRequest): Promise<ProposedPatchSet>;
}

/** A probed candidate ready for contrastive composition. */
export interface ProbeCandidate {
  readonly nodeId: string;
  readonly branchId: string;
  readonly patch: EightSurfacePatch;
  readonly trajectory: ProbeTrajectory;
}

/** Judge-facing candidate with branch and patch identity removed. */
export interface AnonymizedCandidate {
  readonly alias: string;
  readonly deliverable: TrajectoryDeliverable;
  readonly metrics: TrajectoryMetrics;
  readonly stepsSummary: readonly string[];
}

/** Behavioral contrast dimension. */
export type ContrastDimension =
  | 'task_completion'
  | 'steps'
  | 'tool_errors'
  | 'deliverable_quality'
  | 'cost'
  | 'robustness';

/** One evidence-backed behavioral difference. */
export interface BehavioralContrast {
  readonly dimension: ContrastDimension;
  readonly referenceValue: string | number | boolean | null;
  readonly candidateValue: string | number | boolean | null;
  readonly delta?: number;
  readonly evidence: readonly string[];
}

/** Per-candidate assessment. adoptionRatio is clamped to [0, 1]. */
export interface CandidateAssessment {
  readonly alias: string;
  readonly branchId: string;
  readonly nodeId: string;
  readonly selected: boolean;
  readonly adoptionRatio: number;
  readonly contrasts: readonly BehavioralContrast[];
  readonly rationale: string;
  readonly rejectedReason?: string;
}

/** Input for anonymous behavioral composition. */
export interface ComposeRequest {
  readonly task: ProbeTask;
  readonly sessionId: string;
  readonly candidates: readonly ProbeCandidate[];
  readonly reference?: ProbeTrajectory;
  readonly policyId?: string;
  readonly metadata?: ContractMetadata;
}

/**
 * Composition result. selectedPatch is the winning node patch (origin kept);
 * composedPatch is the merged H* (origin 'composed'), null when nothing won.
 */
export interface CompositionResult {
  readonly selectedBranchId: string | null;
  readonly selectedNodeId: string | null;
  readonly selectedTrajectoryId: string | null;
  readonly selectedPatch: EightSurfacePatch | null;
  readonly composedPatch: EightSurfacePatch | null;
  readonly assessments: readonly CandidateAssessment[];
  readonly adoptionRatios: Readonly<Record<string, number>>;
  readonly rationale: string;
  readonly evaluatedAt: number;
}

/** Anonymous behavioral composer. */
export interface IHarnessComposer {
  compose(request: ComposeRequest): Promise<CompositionResult>;
}

/** Input for evidence-backed lesson extraction. */
export interface ReflectionRequest {
  readonly task: ProbeTask;
  readonly sessionId: string;
  readonly tree: DiscoveryTreeSnapshot;
  readonly composition: CompositionResult;
  readonly trajectories: readonly ProbeTrajectory[];
  readonly referenceTrajectory?: ProbeTrajectory;
  readonly recall?: MemoryRecallResult;
  readonly scope: MemoryScope;
  readonly metadata?: ContractMetadata;
}

/** Extracted canonical lessons, positive and negative. */
export interface ReflectionResult {
  readonly lessons: readonly CanonicalLesson[];
  readonly positiveCount: number;
  readonly negativeCount: number;
  readonly diagnostics: readonly string[];
}

/** Evidence-chain reflector. */
export interface IHarnessReflector {
  reflect(request: ReflectionRequest): Promise<ReflectionResult>;
}

// ---------------------------------------------------------------------------
// Dream-RSI: discovery tree, failure taxonomy, active policy, replay
// ---------------------------------------------------------------------------

/** Status of a candidate node in the discovery tree. */
export type DiscoveryNodeStatus =
  | 'proposed'
  | 'scheduled'
  | 'probing'
  | 'succeeded'
  | 'failed'
  | 'pruned';

/**
 * One node of the Dream-RSI discovery tree T. patchId points at the candidate
 * scaffold; trajectoryId/score/failure are filled as probing completes.
 */
export interface DiscoveryNode {
  readonly id: string;
  readonly treeId: string;
  readonly parentId: string | null;
  readonly depth: number;
  readonly branchId: string;
  readonly patchId: string;
  readonly patchOrigin: PatchOrigin;
  readonly purpose: PatchPurpose;
  readonly guidance: GuidanceMode;
  readonly status: DiscoveryNodeStatus;
  readonly slot?: BatchSlotKind;
  readonly round?: number;
  readonly trajectoryId?: string;
  readonly score?: number;
  readonly adoptionRatio?: number;
  readonly failure?: FailureDiagnosis;
  readonly childIds: readonly string[];
  readonly createdAt: number;
  readonly updatedAt: number;
  readonly metadata?: ContractMetadata;
}

/** Aggregate tree statistics cached in snapshots. */
export interface DiscoveryTreeStats {
  readonly nodeCount: number;
  readonly maxDepth: number;
  readonly maxWidth: number;
  readonly scoredNodes: number;
  readonly completedNodes: number;
}

/** Immutable serializable snapshot of one discovery tree. */
export interface DiscoveryTreeSnapshot {
  readonly id: string;
  readonly sessionId: string;
  readonly taskId: string;
  readonly rootId: string;
  readonly nodes: Readonly<Record<string, DiscoveryNode>>;
  readonly policyId?: string;
  readonly stats: DiscoveryTreeStats;
  readonly completed: boolean;
  readonly createdAt: number;
  readonly updatedAt: number;
  readonly metadata?: ContractMetadata;
}

/**
 * Read-only tree view used by replay and orchestration. causalPrefix(id) must
 * return only ancestors of id plus id itself, in root-to-node order; future
 * nodes must never be visible to replay.
 */
export interface IDiscoveryTree {
  readonly id: string;
  readonly rootId: string;
  getNode(nodeId: string): DiscoveryNode | undefined;
  allNodes(): readonly DiscoveryNode[];
  childrenOf(nodeId: string): readonly DiscoveryNode[];
  ancestorsOf(nodeId: string): readonly DiscoveryNode[];
  causalPrefix(nodeId: string): readonly DiscoveryNode[];
  snapshot(): DiscoveryTreeSnapshot;
}

/** Historical tree pool used by offline replay. */
export interface IDiscoveryTreePool {
  add(tree: DiscoveryTreeSnapshot): void;
  get(treeId: string): DiscoveryTreeSnapshot | undefined;
  list(): readonly DiscoveryTreeSnapshot[];
  size(): number;
  pruneTo(maxTrees: number): readonly string[];
  clear(): void;
}

/** Three-way batch slots; exploration is split into domain/invariant tracks. */
export const BATCH_SLOT_KINDS = ['exploit', 'explore_domain', 'explore_invariant', 'recover'] as const;
export type BatchSlotKind = (typeof BATCH_SLOT_KINDS)[number];

/**
 * One planned probe slot for the next round. guidance must be 'guidance_free'
 * for explore_invariant. At most one 'recover' slot may appear in a batch.
 */
export interface BatchSlotPlan {
  readonly slot: BatchSlotKind;
  readonly slotIndex: number;
  readonly branchId: string;
  readonly parentNodeId: string;
  readonly origin: PatchOrigin;
  readonly guidance: GuidanceMode;
  readonly focusSurfaces: readonly HarnessComponentKey[];
  readonly rationale: string;
  readonly expectedUtility?: number;
  readonly memoryHintIds?: readonly string[];
  readonly repairOfNodeId?: string;
  readonly seedPatchIds?: readonly string[];
  readonly metadata?: ContractMetadata;
}

/** Stop condition chosen by plan_grid. */
export type StopCondition =
  | 'first_success'
  | 'budget_exhausted'
  | 'diminishing_returns'
  | 'max_depth';

/** plan_grid output: bounded width/depth and budget for this task. */
export interface SearchGridPlan {
  readonly maxWidth: number;
  readonly maxDepth: number;
  readonly budget: number;
  readonly skipProbing: boolean;
  readonly stopCondition: StopCondition;
  readonly complexity: TaskComplexity;
  readonly rationale: string;
  readonly policyId: string;
}

/** Input to plan_grid. */
export interface PlanGridRequest {
  readonly task: ProbeTask;
  readonly memoryConfidence: number;
  readonly budgetRemaining: number;
  readonly currentDepth: number;
  readonly exploredNodes: number;
  readonly previousFailures?: readonly FailureDiagnosis[];
  readonly policy: MetaSearchPolicy;
}

/** One round's slot portfolio. */
export interface BatchPlan {
  readonly round: number;
  readonly grid: SearchGridPlan;
  readonly policyId: string;
  readonly width: number;
  readonly slots: readonly BatchSlotPlan[];
  readonly createdAt: number;
  readonly metadata?: ContractMetadata;
}

/** Input to selectBatch. */
export interface SelectBatchRequest {
  readonly task: ProbeTask;
  readonly sessionId: string;
  readonly tree: DiscoveryTreeSnapshot;
  readonly grid: SearchGridPlan;
  readonly memoryConfidence: number;
  readonly round: number;
  readonly previousBestNodeId?: string;
  readonly previousFailure?: FailureDiagnosis;
  readonly metadata?: ContractMetadata;
}

/** Online active policy pi_t: plan_grid plus three-way batching. */
export interface IActivePolicy {
  readonly policy: MetaSearchPolicy;
  planGrid(request: PlanGridRequest): SearchGridPlan;
  selectBatch(request: SelectBatchRequest): BatchPlan;
  update(policy: MetaSearchPolicy): void;
}

/**
 * Meta-search policy. slotWeights are normalized over all four slot kinds and
 * govern portfolio composition; recovery is still capped at one slot per batch.
 */
export interface MetaSearchPolicy {
  readonly id: string;
  readonly version: number;
  readonly parentPolicyId?: string;
  readonly createdAt: number;
  readonly maxWidth: number;
  readonly maxDepth: number;
  readonly slotWeights: Readonly<Record<BatchSlotKind, number>>;
  readonly earlyStopThreshold: number;
  readonly minMemoryConfidenceForSkip: number;
  readonly explorationTemperature?: number;
  readonly metadata?: ContractMetadata;
  /** JitRL meta-level hyperparameters; tuned by offline dreaming (plan section 7.3). */
  readonly jit?: Readonly<{
    readonly beta: number;
    readonly lambda: number;
    readonly alpha: number;
    readonly k: number;
    readonly gamma: number;
    readonly similarityThreshold: number;
  }>;
}

/** Multi-budget preference set rho used by Pareto replay. */
export const DREAM_RHO_PREFERENCES = [0, 0.25, 0.5, 0.75, 1] as const;

/** Weights of the verifier-free surrogate reward (expected to sum to 1). */
export interface SurrogateScoreWeights {
  readonly selection: number;
  readonly adoption: number;
  readonly efficiency: number;
  readonly toolErrorPenalty: number;
}

/** Normalized signals behind a surrogate score. */
export interface SurrogateSignals {
  readonly selected: boolean;
  readonly adoptionRatio: number;
  readonly stepEfficiency: number;
  readonly toolErrorRate: number;
}

/** Post-hoc surrogate score s_v, clamped to [0, 1]. */
export interface SurrogateScore {
  readonly nodeId: string;
  readonly score: number;
  readonly signals: SurrogateSignals;
  readonly weights: SurrogateScoreWeights;
  readonly computedAt: number;
  readonly evidence: readonly string[];
}

/** Input to the surrogate scorer. */
export interface SurrogateScoreRequest {
  readonly node: DiscoveryNode;
  readonly trajectory: ProbeTrajectory;
  readonly referenceTrajectory?: ProbeTrajectory;
  readonly composition?: CompositionResult;
  readonly weights: SurrogateScoreWeights;
}

/** Verifier-free post-hoc scorer. */
export interface ISurrogateScorer {
  score(request: SurrogateScoreRequest): SurrogateScore;
}

/** Evaluation of one candidate policy across rho preferences. */
export interface PolicyEvaluation {
  readonly policyId: string;
  readonly hypervolume: number;
  readonly meanQuality: number;
  readonly meanCost: number;
  readonly perRho: Readonly<Record<string, number>>;
  readonly treesEvaluated: number;
}

/** Offline replay request over historical trees. */
export interface OfflineDreamRequest {
  readonly trees: readonly DiscoveryTreeSnapshot[];
  readonly baselinePolicy: MetaSearchPolicy;
  readonly candidatePolicies: readonly MetaSearchPolicy[];
  readonly rhoPreferences?: readonly number[];
  readonly minReplayTrees?: number;
  readonly metadata?: ContractMetadata;
}

/** Result of a dream replay; improved is false unless V(m*) > V(0). */
export interface DreamReplayReport {
  readonly ranAt: number;
  readonly baseline: PolicyEvaluation;
  readonly candidateEvaluations: readonly PolicyEvaluation[];
  readonly best: PolicyEvaluation;
  readonly improved: boolean;
  readonly selectedPolicyId: string;
  readonly replayedTreeIds: readonly string[];
  readonly rhoPreferences: readonly number[];
}

/** Zero-execution offline replay engine. */
export interface IOfflineDreamer {
  replay(request: OfflineDreamRequest): Promise<DreamReplayReport>;
}

// ---------------------------------------------------------------------------
// JitRL: experience, adjustment and step-evaluation contracts (Phase 1, v2)
// ---------------------------------------------------------------------------

/** The three JitRL layers a state, record or decision can belong to. */
export type JitLevel = 'meta' | 'proposal' | 'host_tool';

/**
 * Abstraction of one decision point, shared by the experience store and the
 * policy optimizer. `bucket` is the exact-match key, `tokens` feeds the
 * Jaccard similarity used by nearest-neighbour retrieval, and `summary` is
 * diagnostics/audit only.
 */
export interface AbstractState {
  readonly level: JitLevel;
  /** Exact-match bucket, e.g. `${taskSignature}|${complexity}|${slotKind?}`. */
  readonly bucket: string;
  /** Normalized token set used for Jaccard similarity. */
  readonly tokens: readonly string[];
  /** Human-readable summary; never used for matching. */
  readonly summary: string;
}

/**
 * Terminal outcome of the execution an experience record describes.
 *
 * P6 PR4 (plan section 6.2) requires these to stay distinguishable: a user
 * cancellation is not evidence that the action was bad, and an infrastructure
 * failure is not evidence that the model was bad. Records whose outcome is
 * `cancelled` or `infrastructure_error` carry `learningEligible: false` and a
 * zero `learningTarget`: they are kept for audit and excluded from the learning
 * neighbourhood.
 */
export const EXPERIENCE_OUTCOMES = [
  'succeeded',
  'failed',
  'timeout',
  'aborted',
  'cancelled',
  'infrastructure_error'
] as const;
export type ExperienceOutcome = (typeof EXPERIENCE_OUTCOMES)[number];

/**
 * One stored JitRL experience sample observed at a JitLevel.
 *
 * P6 PR4 (plan section 6.1) adds the association chain
 * PreparedProbe -> ProbeCandidate -> Experience as OPTIONAL fields, so every
 * record written before this round keeps loading unchanged:
 *
 *   decisionId / runId / round / slotIndex      which decision produced the action
 *   scope (scopeKey) / branchId                 which host scope executed it
 *   treeId / nodeId / parentNodeId / trajectoryId  which trajectory it belongs to
 *   level / actionKey / guidance                what was done (guidance IS the
 *                                               guidance provenance)
 *   policyId / policyVersion                    which policy was in force
 *   rewardVersion / provenanceVersion / experienceSchemaVersion  how to read it
 *   observedReturn / attributionBaseline / learningTarget        what it earned
 *   outcome / learningEligible                  whether it may train the policy
 *
 * A record missing `experienceSchemaVersion`/`rewardVersion`/`provenanceVersion`
 * is LEGACY (plan section 6.5): it stays in the log for audit but is excluded
 * from the new-version learning neighbourhood by
 * `ExperienceQuery.excludeLegacy`. Nothing rewrites the original log in place;
 * the migration that marks records is a separate, reversible pass.
 */
export interface ExperienceRecord {
  readonly id: string;
  readonly level: JitLevel;
  readonly state: AbstractState;
  /** MetaAction id, patch signature or tool action key, depending on level. */
  readonly actionKey: string;
  /** Fused, clipped per-step reward r_t. */
  readonly reward: number;
  /** Discounted return G_t from this step onwards. */
  readonly return: number;
  /** Per-source reward breakdown (llm / surrogate / tool / turn / user). */
  readonly rewardSources: Readonly<Record<string, number>>;
  /** Guidance mode in force; keeps invariant slots isolated. */
  readonly guidance: GuidanceMode;
  /** Prior policy that produced this sample (non-stationarity handling). */
  readonly policyId: string;
  readonly sessionId: string;
  readonly treeId?: string;
  readonly nodeId?: string;
  readonly branchId?: string;
  readonly scopeKey?: string;
  /** P6 PR4 association chain (all optional; legacy records omit them). */
  readonly decisionId?: string;
  readonly runId?: string;
  readonly round?: number;
  readonly slotIndex?: number;
  readonly parentNodeId?: string;
  readonly trajectoryId?: string;
  /** `<policyId>@v<version>` of the policy that produced the action. */
  readonly policyVersion?: string;
  /** Reward-model version that produced reward/return (plan section 6.5). */
  readonly rewardVersion?: string;
  /** Provenance-model version that produced the association (plan section 6.5). */
  readonly provenanceVersion?: string;
  /** Stored-record schema version; absent means legacy (pre-PR4). */
  readonly experienceSchemaVersion?: number;
  /** The action's own measured return (plan section 6.3). */
  readonly observedReturn?: number;
  /** Comparable reference/parent baseline for the same context. */
  readonly attributionBaseline?: number;
  /** Value used for the level's estimate (observedReturn - baseline, clipped). */
  readonly learningTarget?: number;
  /** How the execution ended (plan section 6.2); absent means unknown/legacy. */
  readonly outcome?: ExperienceOutcome;
  /** False for cancelled/infrastructure records: audit only, never training. */
  readonly learningEligible?: boolean;
  /** Creation timestamp in ms since epoch (injected clock). */
  readonly createdAt: number;
  /** True once secrets have been redacted from this record. */
  readonly redacted: boolean;
}

/**
 * Nearest-neighbour query against the experience store.
 *
 * Phase 4 (additive): `policyId` and `driftRho` carry the drift down-weighting
 * input from plan section 7.3-4. Both are optional, so every pre-existing
 * construction site keeps compiling and behaving exactly as before. When
 * `policyId` is absent no drift weighting is applied (factor 1); when it is
 * present, records produced by a different policy are weighted by `driftRho`
 * until the same bucket holds k records from the current policy.
 */
export interface ExperienceQuery {
  readonly level: JitLevel;
  readonly state: AbstractState;
  readonly k: number;
  /** Minimum Jaccard similarity for a neighbour to be returned. */
  readonly similarityThreshold: number;
  /** Restrict results to this guidance mode (invariant slots force 'guidance_free'). */
  readonly guidanceFilter?: GuidanceMode;
  /** Causal cutoff: only records with createdAt <= before are visible. */
  readonly before?: number;
  /** Current policy id; when set, stale-policy records are down-weighted. */
  readonly policyId?: string;
  /** Drift down-weight factor in [0, 1] applied to stale-policy records. */
  readonly driftRho?: number;
  /**
   * P6 PR4 (plan section 6.5): when true, records that carry no
   * `experienceSchemaVersion` (or an older one than
   * `minimumExperienceSchemaVersion`) are excluded from the result. Default
   * false keeps every pre-PR4 caller reading the whole level.
   */
  readonly excludeLegacy?: boolean;
  /** Lowest schema version accepted when `excludeLegacy` is set. */
  readonly minimumExperienceSchemaVersion?: number;
  /** Restrict results to records that may train the policy. */
  readonly learningEligibleOnly?: boolean;
}

/** Append-only experience store backing all JitRL levels. */
export interface IExperienceStore {
  append(records: readonly ExperienceRecord[]): Promise<void>;
  query(query: ExperienceQuery): Promise<readonly ScoredExperience[]>;
  size(level?: JitLevel): Promise<number>;
  compact(options: { readonly maxPerBucket: number; readonly halfLifeMs?: number }): Promise<number>;
  export(): AsyncIterable<ExperienceRecord>;
}

/** A neighbour returned by the store, with its similarity in [0, 1]. */
export interface ScoredExperience {
  readonly record: ExperienceRecord;
  readonly similarity: number;
  /** Store-derived retrieval weight; consumers may recompute it. */
  readonly weight?: number;
  /**
   * Phase 4 (additive): the drift factor actually applied to this neighbour,
   * 1 when no drift weighting was requested. Reported so replay diagnostics can
   * prove the down-weighting happened instead of silently shrinking weights.
   */
  readonly driftWeight?: number;
}

/**
 * One candidate action handed to the policy optimizer, with the prior logit
 * z(s, a) of its source. The payload carries the level-specific action object
 * (meta action, patch proposal or tool-call plan) unchanged.
 */
export interface JitCandidate<TPayload = unknown> {
  readonly actionKey: string;
  readonly baseLogit: number;
  readonly source: 'llm' | 'policy_prior' | 'memory_augmented';
  readonly payload: TPayload;
}

/** The optimizer's closed-form correction applied to one candidate. */
export interface JitAdjustment<TPayload = unknown> {
  readonly candidate: JitCandidate<TPayload>;
  /** Q estimate; null when the action has no support and was not explored. */
  readonly q: number | null;
  /** Advantage A = Q - V. */
  readonly advantage: number;
  /** Normalized advantage A-tilde in [-1, 1]. */
  readonly normalizedAdvantage: number;
  /** Adjusted logit z' = z + beta * A-tilde. */
  readonly adjustedLogit: number;
  /** Softmax probability over all adjusted logits. */
  readonly probability: number;
  /** Neighbour support |N(s, a)| for this action. */
  readonly support: number;
  /** True when optimistic exploration produced this Q value. */
  readonly explored: boolean;
}

/** Terminal result of one optimizer decision. */
export interface JitDecision<TPayload = unknown> {
  readonly level: JitLevel;
  /** State value estimate V-hat from the neighbourhood. */
  readonly stateValue: number;
  /** Neighbour count |N(s)|. */
  readonly neighborCount: number;
  readonly adjustments: readonly JitAdjustment<TPayload>[];
  readonly chosen: JitAdjustment<TPayload>;
  /** Diagnostic KL(pi' || pi_prior). */
  readonly klToPrior: number;
  readonly rationale: string;
}

/** JitRL policy optimizer over experience-backed candidates. */
export interface IJitPolicyOptimizer {
  decide<T>(
    level: JitLevel,
    state: AbstractState,
    candidates: readonly JitCandidate<T>[],
    options?: { readonly guidanceFilter?: GuidanceMode; readonly rng?: () => number }
  ): Promise<JitDecision<T>>;
}

/** One fused per-step reward (plan section 6.5). */
export interface StepReward {
  readonly stepIndex: number;
  readonly reward: number;
  readonly sources: Readonly<Record<string, number>>;
  readonly rationale?: string;
}

/**
 * Fuses multi-source per-step signals (llm / surrogate / tool / turn / user)
 * into StepReward entries for one trajectory. The llm judge runs with purpose
 * 'evaluate_steps' and sees anonymized candidates.
 */
export interface IStepEvaluator {
  evaluate(
    trajectory: ProbeTrajectory,
    context: { readonly task: ProbeTask; readonly reference?: ProbeTrajectory }
  ): Promise<readonly StepReward[]>;
}

// ---------------------------------------------------------------------------
// JitRL Phase 4/5: Dream replay hook, L3 host advisor, statistics mirror (v2)
// ---------------------------------------------------------------------------
//
// Every export below is additive to contract version 2. The Dream-RSI replay
// loop is synchronous by construction (see replayTree), so the JitRL simulation
// is expressed as a plain synchronous function type: no Promise, no I/O, no
// timers. Callers budget the neighbour snapshot (already causally truncated)
// before invoking the hook; the hook never queries a store itself.

/**
 * Frontier-node view handed to a replay hook. It carries only the fields replay
 * already exposes, so the hook stays decoupled from DiscoveryNode identity and
 * from the mutable tree.
 */
export interface JitReplayFrontierNode {
  readonly nodeId: string;
  readonly depth: number;
  readonly patchOrigin: PatchOrigin;
  readonly purpose: PatchPurpose;
  readonly guidance: GuidanceMode;
  readonly slot?: BatchSlotKind;
  readonly score?: number;
  readonly createdAt: number;
}

/**
 * Input of one replay-time JitRL simulation step.
 *
 * `experiences` is the caller-budgeted neighbour snapshot: replay must fill it
 * with an ExperienceQuery whose `before` is the replayed tree's createdAt
 * (causal cutoff, plan section 7.3-2). The hook must not widen that window.
 */
export interface JitReplayHookInput {
  readonly treeId: string;
  readonly policyId: string;
  /** Budget preference of the replay point currently being evaluated. */
  readonly rho: number;
  /** Slot weights of the policy under replay, before the Jit correction. */
  readonly slotWeights: Readonly<Record<BatchSlotKind, number>>;
  readonly frontier: JitReplayFrontierNode;
  /** Causally truncated neighbours; the hook is a pure function over them. */
  readonly experiences: readonly ExperienceRecord[];
  /** Hyperparameters of the policy under replay (reuses MetaSearchPolicy.jit). */
  readonly jit: NonNullable<MetaSearchPolicy['jit']>;
  /** Current policy id used for drift down-weighting (plan section 7.3-4). */
  readonly driftRho?: number;
}

/** One slot/action correction produced by a replay hook. */
export interface JitReplayAdjustment {
  readonly actionKey: string;
  /** Slot this correction applies to, when the action maps to one slot. */
  readonly slot?: BatchSlotKind;
  /** Prior weight/probability before the correction. */
  readonly baseWeight: number;
  /** Weight/probability after the correction. */
  readonly adjustedWeight: number;
  /** Q estimate; null when the action had no support and was not explored. */
  readonly q: number | null;
  readonly advantage: number;
  readonly normalizedAdvantage: number;
  /** Neighbour support |N(s, a)|. */
  readonly support: number;
  /** True when optimistic exploration produced this Q value. */
  readonly explored: boolean;
}

/** Diagnostics of one replay-time JitRL simulation step. */
export interface JitReplayHookDiagnostics {
  readonly level: JitLevel;
  /** State value estimate V-hat from the neighbour snapshot. */
  readonly stateValue: number;
  /** Neighbour count |N(s)| within the causal window. */
  readonly neighborCount: number;
  /** KL(pi' || pi_prior) of the corrected portfolio against the prior. */
  readonly klToPrior: number;
  readonly adjustments: readonly JitReplayAdjustment[];
  /** True when the hook could not apply a correction and kept the prior. */
  readonly degraded?: boolean;
  readonly notes?: readonly string[];
}

/**
 * Result of one replay-time JitRL simulation step. `slotWeights` is the
 * corrected portfolio and must stay normalized over all four slot kinds; a
 * hook that cannot correct anything returns the prior weights unchanged.
 */
export interface JitReplayHookResult {
  readonly slotWeights: Readonly<Record<BatchSlotKind, number>>;
  readonly diagnostics: JitReplayHookDiagnostics;
}

/**
 * Synchronous, side-effect-free JitRL simulation injected into Dream replay.
 *
 * Implementations must be pure and synchronous: replay is a synchronous
 * function over recorded data, so the hook may not await, read files, hit the
 * network or mutate its input. Any neighbour lookup happens in the caller.
 */
export type JitReplayHook = (input: JitReplayHookInput) => JitReplayHookResult;

/**
 * Per-tree, per-rho JitRL diagnostics attached by Dream replay. This is the
 * Dream-layer aggregation the replay report exposes; it is additive, so a
 * replay outcome without a hook simply omits it.
 */
export interface DreamJitDiagnostics {
  readonly treeId: string;
  readonly policyId: string;
  /** Number of frontier nodes the hook actually consulted. */
  readonly hookCalls: number;
  /** Total neighbours the hook saw after the causal cutoff. */
  readonly neighborsUsed: number;
  /** Mean KL(pi' || pi_prior) across hook calls; 0 when no call happened. */
  readonly meanKlToPrior: number;
  /** Mean state value estimate across hook calls. */
  readonly meanStateValue: number;
  /** Drift down-weight factor in force during this replay. */
  readonly driftRho: number;
  /** Causal cutoff used for the neighbour snapshot (normally tree.createdAt). */
  readonly causalCutoff?: number;
  /** True when at least one hook call degraded to the unchanged prior. */
  readonly degraded: boolean;
  /** Human-readable evidence lines; safe to append to ReplayTreeOutcome.evidence. */
  readonly evidence: readonly string[];
}

/**
 * L3 host-advisor decision kinds. 'deny' is deliberately absent: the advisor may
 * annotate a decision or ask the user, but it must never block a tool call on
 * its own (plan section 3.3, gate mode is user-approval only).
 */
export const HOST_ADVISOR_DECISION_KINDS = ['advisory', 'ask', 'noop'] as const;
export type HostAdvisorDecisionKind = (typeof HOST_ADVISOR_DECISION_KINDS)[number];

/** One observed host tool call, used to build the L3 abstract state. */
export interface HostToolCallObservation {
  readonly toolName: string;
  readonly actionKey?: string;
  readonly at?: number;
  readonly isError?: boolean;
  readonly exitCode?: number;
  readonly summary?: string;
}

/** Coarse working-directory digest; never the raw file contents. */
export interface WorkingDirectorySummary {
  readonly path: string;
  readonly fileCount?: number;
  readonly topExtensions?: readonly string[];
  readonly truncated?: boolean;
}

/**
 * Input of one L3 host-advisor evaluation. `state` is always a 'host_tool'
 * AbstractState, so the advisor can reuse the shared experience retriever.
 */
export interface HostAdvisorRequest {
  readonly level: 'host_tool';
  readonly sessionId?: string;
  readonly branchId?: string;
  readonly isInvariant?: boolean;
  readonly state: AbstractState;
  /** Most recent host tool calls, newest last. */
  readonly recentTools: readonly HostToolCallObservation[];
  readonly errors: readonly ToolErrorRecord[];
  readonly workingDirectory?: WorkingDirectorySummary;
  /** Advisor mode in force; 'gate' may ask the user but never denies. */
  readonly mode: 'advisory' | 'gate';
  readonly adviseThreshold: number;
  readonly gateThreshold: number;
  readonly minSupport: number;
  readonly policyId?: string;
  /** Drift down-weight factor in [0, 1] for stale-policy experience. */
  readonly driftRho?: number;
  /** Injected wall clock (ms since epoch). */
  readonly now?: number;
  readonly metadata?: ContractMetadata;
}

/** Evidence behind one advisor decision; diagnostics only, never injected. */
export interface HostAdvisorDiagnostics {
  readonly actionKey: string;
  readonly meanReturn: number | null;
  readonly support: number;
  readonly stateValue: number;
  readonly advantage: number;
  readonly threshold: number;
  readonly mode: 'advisory' | 'gate';
}

/**
 * Advisory decision: annotate the turn with a short suggestion. The rendered
 * text is capped by the implementation (<= 300 tokens, plan section 8 Phase 5).
 */
export interface HostAdvisorAdvisoryDecision {
  readonly kind: 'advisory';
  readonly text: string;
  /** Anti-patterns rendered separately; never phrased as recommendations. */
  readonly antiPatterns?: readonly string[];
  readonly diagnostics?: HostAdvisorDiagnostics;
}

/** Gate decision: hand the call to the user for approval. Never an automatic deny. */
export interface HostAdvisorAskDecision {
  readonly kind: 'ask';
  readonly reason: string;
  readonly suggestedActionKey?: string;
  readonly diagnostics?: HostAdvisorDiagnostics;
}

/** Do-nothing decision: no neighbours, low support or advantage above threshold. */
export interface HostAdvisorNoopDecision {
  readonly kind: 'noop';
  readonly reason?: string;
  readonly diagnostics?: HostAdvisorDiagnostics;
}

/** Tri-state L3 decision discriminated by 'kind'. */
export type HostAdvisorDecision =
  | HostAdvisorAdvisoryDecision
  | HostAdvisorAskDecision
  | HostAdvisorNoopDecision;

/**
 * One aggregated JitRL statistic row mirrored to the memory bridge: per
 * (bucket, actionKey, level) sample count, mean return and variance. Raw
 * records are never mirrored; the aggregate is the only outbound shape.
 */
export interface JitStatsAggregate {
  readonly bucket: string;
  readonly actionKey: string;
  readonly level: JitLevel;
  readonly n: number;
  readonly meanReturn: number;
  readonly variance: number;
  /** Namespace the aggregate belongs to; filled by namespaceFor(level). */
  readonly namespace?: string;
  readonly policyId?: string;
  /** Drift factor applied to the contributing records, 1 when none. */
  readonly driftRhoApplied?: number;
  readonly updatedAt?: number;
  /**
   * P6 PR4 (plan section 6.5): reward-model version of the contributing records.
   * Aggregates built from legacy (mis-attributed) records are published with
   * `legacy: true` and a `rewardVersion` below the current one, so a backend
   * cannot hand the old bias back after the local log was migrated.
   */
  readonly rewardVersion?: string;
  readonly provenanceVersion?: string;
  /** True when any contributing record lacked per-execution provenance. */
  readonly legacy?: boolean;
  /** Number of contributing records excluded as legacy/not learning eligible. */
  readonly legacyExcluded?: number;
}

/** Outcome of one mirror write. */
export interface JitMirrorResult {
  readonly written: number;
  readonly skipped: number;
  readonly namespaces: readonly string[];
  readonly degraded: boolean;
  readonly diagnostics: readonly string[];
}

/**
 * Optional mirror of JitRL statistics into the governed memory bridge. Writes
 * are aggregate-only (plan section 7.2) and namespace-isolated per level, so a
 * disabled mirror costs zero backend calls instead of a degraded write.
 */
export interface IJitMirrorStore {
  mirror(aggregates: readonly JitStatsAggregate[]): Promise<JitMirrorResult>;
  /** Stable namespace for one level, e.g. `${prefix}/jitrl/${level}`. */
  namespaceFor(level: JitLevel): string;
}

// ---------------------------------------------------------------------------
// Orchestration facade (integrator-owned implementation)
// ---------------------------------------------------------------------------

/** Optional per-run budget override, clamped by configuration. */
export interface RunBudgetOverride {
  readonly maxOnlineRolloutBudget?: number;
  readonly maxWidth?: number;
  readonly maxDepth?: number;
}

/** Run request handed to the orchestrator by the Cordis entry point. */
export interface EvoHarnessRunRequest {
  readonly runId?: string;
  readonly sessionId: string;
  readonly task: ProbeTask;
  readonly trigger: TriggerMode;
  readonly budgetOverride?: RunBudgetOverride;
  readonly dryRun?: boolean;
  readonly metadata?: ContractMetadata;
}

/** Terminal outcome of an evolution run. */
export type EvoHarnessRunOutcome = 'skipped' | 'no_probe' | 'probed' | 'composed' | 'failed';

/** Summary returned to the host; no internal mutable objects leak out. */
export interface EvoHarnessRunResult {
  readonly runId: string;
  readonly sessionId: string;
  readonly taskId: string;
  readonly outcome: EvoHarnessRunOutcome;
  readonly trigger: TriggerMode;
  readonly treeId?: string;
  readonly selectedNodeId?: string;
  readonly selectedBranchId?: string;
  readonly selectedTrajectoryId?: string;
  readonly composedPatchId?: string;
  readonly probesRun: number;
  readonly lessonsCommitted: number;
  readonly failure?: {
    readonly category: FailureCategory;
    readonly message: string;
  };
  readonly diagnostics: readonly string[];
  readonly startedAt: number;
  readonly endedAt: number;
  readonly metadata?: ContractMetadata;
}

/** Top-level runtime facade implemented by src/orchestrator.ts. */
export interface IEvoHarnessOrchestrator {
  run(request: EvoHarnessRunRequest): Promise<EvoHarnessRunResult>;
  dispose(): Promise<void>;
}
